503	    template <typename T>
504	    String parsePattern(const String & pattern, std::vector<Action<T>> & instructions) const
505	    {
506	        String result;
507	
508	        const char * pos = pattern.data();
509	        const char * end = pos + pattern.size();
510	
511	        /// Add shift to previous action; or if there were none, add noop action with shift.
512	        auto add_shift = [&](size_t amount)
513	        {
514	            if (instructions.empty())
515	                instructions.emplace_back(&Action<T>::noop);
516	            instructions.back().shift += amount;
517	        };
518	
519	        /// If the argument was DateTime, add instruction for printing. If it was date, just shift (the buffer is pre-filled with default values).
520	        auto add_instruction_or_shift = [&](typename Action<T>::Func func [[maybe_unused]], size_t shift)
521	        {
522	            if constexpr (std::is_same_v<T, UInt32>)
