43	struct AddNanosecondsImpl
44	{
45	    static constexpr auto name = "addNanoseconds";
46	
47	    static inline NO_SANITIZE_UNDEFINED DecimalUtils::DecimalComponents<DateTime64>
48	    execute(DecimalUtils::DecimalComponents<DateTime64> t, Int64 delta, const DateLUTImpl &, UInt16 scale = DataTypeDateTime64::default_scale)
49	    {
50	        Int64 multiplier = DecimalUtils::scaleMultiplier<DateTime64>(9 - scale);
51	        auto division = std::div(t.fractional * multiplier + delta, static_cast<Int64>(1000000000));
52	        return {t.whole * multiplier + division.quot, t.fractional * multiplier + delta};
53	    }
54	
55	    static inline NO_SANITIZE_UNDEFINED DateTime64
56	    execute(DateTime64 t, Int64 delta, const DateLUTImpl &, UInt16 scale = 0)
57	    {
58	        Int64 multiplier = DecimalUtils::scaleMultiplier<DateTime64>(9 - scale);
59	        return t * multiplier + delta;
60	    }
61	
62	    static inline NO_SANITIZE_UNDEFINED UInt32 execute(UInt32 t, Int64 delta, const DateLUTImpl &, UInt16 = 0)
63	    {
64	        Int64 multiplier = DecimalUtils::scaleMultiplier<DateTime64>(9);
65	        return t * multiplier + delta;
66	    }
67	
68	    static inline NO_SANITIZE_UNDEFINED DateTime64 execute(UInt16, Int64, const DateLUTImpl &, UInt16 = 0)
69	    {
70	        throw Exception("addNanoSeconds() cannot be used with Date", ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
71	    }
72	
73	    static inline NO_SANITIZE_UNDEFINED DateTime64 execute(Int32, Int64, const DateLUTImpl &, UInt16 = 0)
74	    {
75	        throw Exception("addNanoSeconds() cannot be used with Date32", ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
76	    }
77	};
