471	    template <typename FromVectorType, typename ToVectorType>
472	    void NO_INLINE vectorConstant(const FromVectorType & vec_from, ToVectorType & vec_to, Int64 delta, const DateLUTImpl & time_zone, UInt16 scale) const
473	    {
474	        size_t size = vec_from.size();
475	        vec_to.resize(size);
476	
477	        for (size_t i = 0; i < size; ++i)
478	            vec_to[i] = transform.execute(vec_from[i], checkOverflow(delta), time_zone, scale);
