482	    void vectorVector(const FromVectorType & vec_from, ToVectorType & vec_to, const IColumn & delta, const DateLUTImpl & time_zone, UInt16 scale) const
483	    {
484	        size_t size = vec_from.size();
485	        vec_to.resize(size);
486	
487	        castTypeToEither<
488	            ColumnUInt8, ColumnUInt16, ColumnUInt32, ColumnUInt64,
489	            ColumnInt8, ColumnInt16, ColumnInt32, ColumnInt64,
490	            ColumnFloat32, ColumnFloat64>(
