509	    template <typename Value>
510	    static Int64 checkOverflow(Value val)
511	    {
512	        Int64 result;
513	        if (accurate::convertNumeric<Value, Int64, false>(val, result))
514	            return result;
515	        throw DB::Exception("Numeric overflow", ErrorCodes::DECIMAL_OVERFLOW);
