539	    static ColumnPtr execute(Transform transform, const ColumnsWithTypeAndName & arguments, const DataTypePtr & result_type, UInt16 scale = 0)
540	    {
541	        using FromValueType = typename FromDataType::FieldType;
542	        using FromColumnType = typename FromDataType::ColumnType;
543	        using ToColumnType = typename ToDataType::ColumnType;
544	
545	        auto op = Adder<Transform>{std::move(transform)};
546	
547	        const DateLUTImpl & time_zone = extractTimeZoneFromFunctionArguments(arguments, 2, 0);
548	
549	        const ColumnPtr source_col = arguments[0].column;
550	
551	        auto result_col = result_type->createColumn();
552	        auto col_to = assert_cast<ToColumnType *>(result_col.get());
553	
554	        const IColumn & delta_column = *arguments[1].column;
555	        if (const auto * sources = checkAndGetColumn<FromColumnType>(source_col.get()))
556	        {
557	            if (const auto * delta_const_column = typeid_cast<const ColumnConst *>(&delta_column))
558	                op.vectorConstant(sources->getData(), col_to->getData(), delta_const_column->getInt(0), time_zone, scale);
559	            else
560	                op.vectorVector(sources->getData(), col_to->getData(), delta_column, time_zone, scale);
561	        }
562	        else if (const auto * sources_const = checkAndGetColumnConst<FromColumnType>(source_col.get()))
563	        {
564	            op.constantVector(
565	                sources_const->template getValue<FromValueType>(),
566	                col_to->getData(), delta_column, time_zone, scale);
567	        }
568	        else
569	        {
570	            throw Exception(ErrorCodes::ILLEGAL_COLUMN, "Illegal column {} of first argument of function {}",
571	                            arguments[0].column->getName(), Transform::name);
572	        }
573	
574	        return result_col;
