-- Stabilized: use only fixed Date32 values and explicit timezones so the result
-- does not depend on the server local timezone (was flaky).

SELECT dateDiff('day', toDate32('2000-01-01'), toDate32('2100-01-01'));
SELECT dateDiff('day', toDate32('2100-01-01'), toDate32('2000-01-01'));
SELECT dateDiff('month', toDate32('1925-01-01'), toDate32('1925-03-01'));
SELECT dateDiff('quarter', toDate32('1925-01-01'), toDate32('1925-07-01'));
SELECT dateDiff('year', toDate32('1925-01-01'), toDate32('2025-01-01'));
SELECT dateDiff('day', toDateTime('2000-01-01 00:00:00', 'UTC'), toDate32('2000-01-02'));
SELECT dateDiff('day', toDate32('2000-01-01'), toDateTime('2000-01-02 00:00:00', 'UTC'));

